// Coupling feasibility probe using the unchanged 50k fixture. Rectangular gas box;
// this is NOT a validated gas representation of the MX301 machine.
#include "powder/granular.hpp"
#include "powder/coupled.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <chrono>
#include <cmath>
using namespace powder;
int main(int argc,char** argv){try{
 if(argc!=5&&argc!=6)throw std::runtime_error("initial.bin output steps batch required");std::filesystem::path out(argv[2]);bool adaptive=argc==6&&std::string(argv[5])=="adaptive";unsigned steps=std::stoul(argv[3]),batch=std::stoul(argv[4]);if(!steps||steps>20000||!batch||batch>8)throw std::runtime_error("probe step/batch range");if(std::filesystem::exists(out))throw std::runtime_error("output exists");std::filesystem::create_directories(out);
 GranularConfig c;c.count=50000;c.dt=.000375f;c.iterations=16;c.test_mixer=true;c.binary_materials=true;c.rotation=true;c.rolling_friction=.02f;c.cross_friction=.35f;c.candidates=true;c.candidate_reuse=true;c.kernel_optimize=true;c.coupled_air=true;
 c.materials[0].radius_m=.0063647064;c.materials[0].density_kg_m3=900;c.materials[0].particle_friction=.3;c.materials[0].wall_friction=.25;c.materials[1].radius_m=.005;c.materials[1].density_kg_m3=1500;c.materials[1].particle_friction=.5;c.materials[1].wall_friction=.45;
 if(std::filesystem::file_size(argv[1])!=c.count*sizeof(Grain))throw std::runtime_error("wrong fixture count");std::vector<Grain> initial(c.count),velocity(c.count);std::ifstream in(argv[1],std::ios::binary);in.read(reinterpret_cast<char*>(initial.data()),initial.size()*sizeof(Grain));if(!in)throw std::runtime_error("fixture read failed");
 GasConfig gc;gc.cells={16,10,10};gc.h=.1;gc.boundary_pa={};GasGrid gas(gc);Vec3 origin{-.8,-.5,-.5};double volume=0,mass=0;std::vector<double> alpha(gas.cells.size());for(const auto& p:initial){const auto& m=c.materials[p.w==0?0:1];double v=m.mass_kg()/m.density_kg_m3;volume+=v;mass+=m.mass_kg();for(auto a:gas.stencil({p.x-origin.x,p.y-origin.y,p.z-origin.z}))alpha[a.first]+=v*a.second/.001;}
 for(std::size_t i=0;i<alpha.size();++i){if(alpha[i]>.65)throw std::runtime_error("initial porosity contract");gas.cells[i].epsilon=1-alpha[i];}gas.initialize_pressure();const double initialGasMass=gas.mass();
 GranularGPU gpu(c,initial,velocity);GranularGasField f;f.cells=gc.cells;f.origin={float(origin.x),float(origin.y),float(origin.z)};f.h=float(gc.h);f.viscosity=float(gc.viscosity());f.velocity_density.resize(gas.cells.size());f.gradient_epsilon.resize(gas.cells.size());
 double gasWall=0,gpuWall=0,exchangeWall=0,maxVolumeError=0,maxGasSpeed=0;auto start=std::chrono::steady_clock::now();unsigned done=0;std::ofstream trace(out/"trace.csv");trace<<"time,gas_mass_error,volume_error,max_gas_speed\n";
 while(done<steps){unsigned n=std::min(batch,steps-done);if(done<2672)n=std::min(n,2672-done);double dt=double(c.dt)*n;auto begin=std::chrono::steady_clock::now();
  // Conservative acoustic bound uses the minimum permitted porosity and 100 m/s speed.
  if(adaptive){double remaining=dt;while(remaining>1e-14){double subdt=std::min(remaining,gas.explicit_dt_limit());gas.step(subdt,{0,0,-9.81});remaining-=subdt;}}else{unsigned sub=unsigned(std::ceil(dt/(.39*gc.h/(3*(100+std::sqrt(287.05*gc.temperature_k/.35))))));for(unsigned j=0;j<sub;++j)gas.step(dt/sub,{0,0,-9.81});}gasWall+=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();
  begin=std::chrono::steady_clock::now();for(int z=0;z<gc.cells[2];++z)for(int y=0;y<gc.cells[1];++y)for(int x=0;x<gc.cells[0];++x){int i=gas.index(x,y,z),q[3]{x,y,z};auto u=gas.velocity(i);f.velocity_density[i]={float(u.x),float(u.y),float(u.z),float(gas.cells[i].mass/(gas.cells[i].epsilon*.001))};Grain a{0,0,0,float(gas.cells[i].epsilon)};float* g=&a.x;for(int k=0;k<3;++k){int lo[3]{x,y,z},hi[3]{x,y,z};lo[k]=std::max(0,q[k]-1);hi[k]=std::min(gc.cells[k]-1,q[k]+1);g[k]=float((gas.pressure(gas.index(hi[0],hi[1],hi[2]))-gas.pressure(gas.index(lo[0],lo[1],lo[2])))/(2*gc.h));}f.gradient_epsilon[i]=a;}
  gpu.set_gas_field(f);exchangeWall+=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();begin=std::chrono::steady_clock::now();gpu.advance(n,done<2672?0:30,false);gpuWall+=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();
  begin=std::chrono::steady_clock::now();auto ex=gpu.gas_exchange();double mapped=0;for(std::size_t i=0;i<ex.impulse_volume.size();++i){const auto& a=ex.impulse_volume[i];double fraction=a.w/.001;if(!std::isfinite(fraction)||fraction<0||fraction>.65)throw std::runtime_error("mapped porosity outside contract");if(dt*ex.drag_rate_kg_s[i]/gas.cells[i].mass>.1)throw std::runtime_error("gas feedback timestep unresolved");gas.cells[i].epsilon=1-fraction;gas.cells[i].momentum.x+=a.x;gas.cells[i].momentum.y+=a.y;gas.cells[i].momentum.z+=a.z;mapped+=a.w;auto u=gas.velocity(int(i));double speed=std::hypot(u.x,u.y,u.z);if(!std::isfinite(speed)||speed>100)throw std::runtime_error("coupled gas speed contract");maxGasSpeed=std::max(maxGasSpeed,speed);}
  maxVolumeError=std::max(maxVolumeError,std::abs(mapped-volume));if(std::abs(mapped-volume)>volume*2e-5)throw std::runtime_error("GPU volume ledger mismatch");double gm=gas.mass()+gas.boundary_mass_out-initialGasMass;if(std::abs(gm)>1e-10)throw std::runtime_error("gas mass ledger mismatch");done+=n;trace<<std::setprecision(17)<<gpu.time()<<','<<gm<<','<<mapped-volume<<','<<maxGasSpeed<<'\n';exchangeWall+=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();
 }
 std::ofstream gasFile(out/"gas.csv");gasFile<<std::setprecision(17)<<"mass,eps,mx,my,mz\n";for(const auto& q:gas.cells)gasFile<<q.mass<<','<<q.epsilon<<','<<q.momentum.x<<','<<q.momentum.y<<','<<q.momentum.z<<'\n';
 double wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto final=gpu.snapshot();std::ofstream bin(out/"final.bin",std::ios::binary);bin.write(reinterpret_cast<const char*>(final.data()),final.size()*sizeof(Grain));std::ofstream result(out/"result.json");result<<std::setprecision(17)<<"{\"count\":50000,\"particle_mass_kg\":"<<mass<<",\"time_s\":"<<gpu.time()<<",\"wall_s\":"<<wall<<",\"rate\":"<<gpu.time()/wall<<",\"gas_s\":"<<gasWall<<",\"gpu_s\":"<<gpuWall<<",\"exchange_s\":"<<exchangeWall<<",\"gas_balance_kg\":"<<gas.mass()+gas.boundary_mass_out-initialGasMass<<",\"max_volume_error_m3\":"<<maxVolumeError<<",\"max_gas_speed\":"<<maxGasSpeed<<",\"adaptive_gas_dt\":"<<(adaptive?"true":"false")<<",\"batch\":"<<batch<<",\"machine_gas_geometry_validated\":false,\"full_requirements_pass\":false}";if(!result||!bin||!trace)throw std::runtime_error("output write failed");std::cout<<"coupled probe rate="<<gpu.time()/wall<<" gas="<<gasWall<<" gpu="<<gpuWall<<" exchange="<<exchangeWall<<'\n';
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
